    "scriptText": "\"안녕하세요. 윤서연 강사입니다. 폐질환자 전문간병사 교육을 시작하겠습니다.  \n 폐질환 환자 돌봄의 첫 원칙은, **의료진의 치료계획과 지시 범위 안에서 안전을 지키는 것**입니다.  \n 호흡이 평소보다 빨라지거나 힘들어 보이는지, 입술이나 손끝이 파래지는 **청색증**이 있는지, 의식이 흐려지거나 갑자기 **불안**해하는지 살펴보세요.  \n 이상 징후를 발견하면 혼자 판단하지 말고 **즉시 간호사나 담당 의료진에게 알립니다**.  \n **산소 유량을 임의로 조절하거나 흡입 약물을 대신 결정해서는 안 됩니다**.  \n 돌봄 중에는 **손 위생**을 지키고, 이동과 체위 변경은 환자의 **숨찬 정도를 확인하며 천천히** 돕습니다.  \n 기침이나 가래 배출이 어려울 때에도 **무리하게 시행하지 말고 의료진의 지시**를 따르세요.  \n 전문간병사는 환자의 작은 변화를 빠르게 알아차리고 정확히 보고하는 사람입니다.  \n 안전한 돌봄으로 환자의 회복을 함께 돕겠습니다. 감사합니다.\"",
