        "title": "제1장. 호흡기계 해부생리 및 주요 폐질환의 특성",
        "content": "### 제1장. 호흡기계 해부생리 및 주요 폐질환의 특성\n\n#### 1. 정상 호흡 vs 비정상 호흡의 기전\n- **정상 성인 호흡**: 분당 12~20회, 규칙적이고 힘들이지 않는 복식-흉식 협응 호흡.\n- **빈호흡(Tachypnea)**: 분당 20회 이상의 빠른 호흡. 감염, 저산소혈증, 통증, 발열, 불안 시 발생.\n- **서호흡(Bradypnea)**: 분당 10~12회 미만의 느린 호흡. 중추신경 억제, 이산화탄소 축적(CO2 Narcosis), 뇌압 상승 시 발생.\n- **보조근 사용 호흡**: 흉쇄유돌근, 사각근, 늑간근, 승모근 등을 사용하여 어깨를 들썩이며 숨을 쉬는 상태로 심각한 호흡곤란의 징후.\n- **역설적 호흡(Paradoxical Breathing)**: 숨을 들이쉴 때 복부가 꺼지고, 내쉴 때 나오는 상태로 횡격막 피로 및 임박한 호흡부전을 의미.\n\n#### 2. 주요 폐질환의 임상적 특성\n| 질환명 | 주요 병태생리 및 원인 | 간병 시 특별 관찰 사항 |\n| :--- | :--- | :--- |\n| **만성폐쇄성폐질환 (COPD)** | 만성기관지염과 폐기종으로 인한 비가역적 기류 제한. 기도 폐쇄 및 폐포 파괴. | **고농도 산소 주입 절대 금기** (저산소 드라이브 억제로 호흡정지 초래 위험). 계단/이동 시 호흡곤란 극심. |\n| **폐렴 (Pneumonia)** | 세균, 바이러스 또는 음식물/타액 흡인에 의한 폐 실질의 급성 염증. | 발열, 화농성 객담, 식사 중 사레들림(흡인), 노인의 경우 비전형적 증상(열 없이 무기력, 식욕부진, 낙상). |\n| **기관지 천식 (Asthma)** | 기관지 과민반응으로 인한 가역적 기도 수축, 부종, 점액 과다분비. | 호흡 시 쌕쌕거리는 천명음(Wheezing), 마른기침, 야간 호흡곤란, 흡입제(속효성 기관지확장제) 위치 숙지. |\n| **폐색전증 (Pulmonary Embolism)** | 심부정맥 혈전(DVT)이 폐동맥을 막아 급성 산소 교환 마비 유발. | 장기 와상 환자가 갑자기 호흡곤란, 흉통, 청색증, 식은땀 호소 시 초응급 상황. |\n\n---"
