    "scriptText": "\"안녕하세요. **대한노인돌봄서비스협회 중앙회, 사 다시 일 강의실의 AI 가상 강사**입니다.  \n 근골격계질환 전문간병사 교육을 시작하기 전에, 오늘 배울 내용과 현장에서 먼저 지켜야 할 **안전 원칙**을 함께 확인하겠습니다.  \n 이 안내는 실습과 개인별 돌봄 지시를 대신하지 않습니다.  \n 이 과정에서는 **경추와 척수손상, 허리디스크, 관절염, 골절, 골다공증과 수술 후 재활에 필요한 일상 보조**를 배웁니다.  \n 병명을 외우는 데서 그치지 않고, **평소와 다른 변화를 알아차리고 안전하게 돕고 정확하게 보고하는 연습**을 합니다.  \n 환자마다 치료 단계와 생활 습관, 도움의 정도가 다르다는 점을 기억해 주세요.  \n **통증과 움직임의 한계를 먼저 듣고, 수술이나 손상에 따라 허용된 자세와 체중부하를 확인**합니다.  \n **마비된 팔을 잡아당기거나 아픈 관절을 억지로 펴지 않습니다**.  \n **새 마비, 감각 변화, 배뇨 장애는 즉시 보고**합니다.  \n **보행기, 휠체어, 보조기, 이동 리프트는 환자에게 맞는 크기와 허용 하중, 손상 여부를 확인**합니다.  \n **리프트와 슬링은 서로 맞는 제품인지 확인하고 교육받은 인원과 절차**를 지킵니다.  \n **혼자 들기 어렵다면 무리하지 말고 도움을 요청**합니다.  \n 한 가지 상황을 생각해 보겠습니다. **허리 수술 뒤 환자가 혼자 일어나겠다고 합니다. 걸을 수 있다고 추측하지 말고 수술팀이 정한 이동 방법을 확인**합니다.  \n **재활치료사가 교육한 방법을 보조하고 통증과 어지럼을 기록**합니다.  \n 지금 사례에서 직접 본 사실, 아직 모르는 것, 담당자에게 확인할 내용을 구분해 보세요.  \n **운동 중 통증이 심해져도 정해진 횟수를 끝내야 할까요? 정답은 다음과 같습니다. 아닙니다. 중단하고 변화와 발생 상황을 담당자에게 보고하여 계획을 확인**합니다.  \n 기록에는 **발견 시각, 환자가 한 말, 직접 관찰한 변화, 알린 담당자와 받은 지시, 도움 뒤의 반응**을 적습니다. **확인하지 않은 수치나 진단은 만들어 넣지 않습니다**.  \n **도구 사용 전에는 대상자와 처방, 기구 상태와 도움 인원, 주변 안전을 확인**하세요.  \n **방법을 모르면 멈추고 질문하는 것이 안전한 돌봄**입니다.  \n 이제 본 교안에서 사례를 읽고 모의 실습과 문제 풀이로 이어가겠습니다. 환자의 의사를 존중하며 작은 변화를 놓치지 않는 돌봄을 함께 배워 봅시다.\"",
